import { queryOptions } from "@tanstack/react-query"

import { getCards } from "@/features/checkout-card/api/get-cards.api"
import { cardKeys } from "@/features/checkout-card/api/query-keys"

export const cardsQueryOptions = queryOptions({
  queryKey: cardKeys.all,
  queryFn: getCards,
  // The dummy list only changes in this cache. With a real API, remove this line.
  staleTime: Infinity
})

import { DUMMY_CARDS } from "@/features/checkout-card/constants/cards.constants"
import type { SavedCard } from "@/features/checkout-card/schemas/card.schema"

/** No request yet: replace the body with a request to your API, `api.get(path, { schema })`. */
export async function getCards(): Promise<SavedCard[]> {
  return DUMMY_CARDS
}

export const cardKeys = {
  all: ["cards"] as const
}

import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { saveCard } from "@/features/checkout-card/api/save-card.api"
import { tokenizeCard } from "@/features/checkout-card/api/tokenize-card"
import { CARDS_PATH } from "@/features/checkout-card/constants/cards.constants"
import { server } from "@/test/server"

const input = {
  cardNumber: "5400360000000003",
  holderName: "Ömer Gülçiçek",
  expiry: "1230",
  cvv: "123"
}

describe("tokenizeCard", () => {
  it("keeps only what is safe to send", async () => {
    const card = await tokenizeCard(input)

    expect(card).toMatchObject({
      cardAssociation: "MASTER_CARD",
      lastFourDigits: "0003",
      expireMonth: "12",
      expireYear: "2030",
      cardHolderName: "Ömer Gülçiçek"
    })
    expect(JSON.stringify(card)).not.toContain(input.cardNumber)
    expect(card).not.toHaveProperty("cvv")
  })
})

describe("saveCard", () => {
  it("posts the token without the card number or CVV", async () => {
    let body = ""
    server.use(
      http.post(`${siteConfig.apiUrl}${CARDS_PATH}`, async ({ request }) => {
        body = await request.text()
        return HttpResponse.json({ status: 201, message: "Created" }, { status: 201 })
      })
    )

    const saved = await saveCard(await tokenizeCard(input))

    expect(body).toContain("tok_dummy_")
    expect(body).toContain("0003")
    expect(JSON.parse(body)).toMatchObject({ expireMonth: "12", expireYear: "2030" })
    expect(body).not.toContain(input.cardNumber)
    expect(body).not.toContain("cvv")
    expect(saved.cardBankName).toBeNull()
  })
})

import { api } from "@/lib/api"

import { CARDS_PATH } from "@/features/checkout-card/constants/cards.constants"
import { savedCardResponseSchema } from "@/features/checkout-card/schemas/card.schema"
import type { SavedCard } from "@/features/checkout-card/schemas/card.schema"

/**
 * Sends the token and display details only. The request is real, but DummyJSON only answers
 * 201 Created, so the result is built here. iyzico answers with the stored card, bank name
 * included; with your API, return its answer.
 */
export async function saveCard(card: Omit<SavedCard, "cardBankName">): Promise<SavedCard> {
  await api.post(CARDS_PATH, card, { schema: savedCardResponseSchema })

  return { ...card, cardBankName: null }
}

import { getCardType } from "@virastack/mask"

import type {
  CardAssociation,
  CardFormInput,
  SavedCard
} from "@/features/checkout-card/schemas/card.schema"

const ASSOCIATIONS: Record<ReturnType<typeof getCardType>, CardAssociation | null> = {
  visa: "VISA",
  mastercard: "MASTER_CARD",
  amex: "AMERICAN_EXPRESS",
  troy: "TROY",
  unknown: null
}

/**
 * The one place to connect a payment provider. With iyzico, its checkout form takes the card and
 * your server receives the `cardToken`. Card number and CVV must never reach your server or be
 * stored.
 */
export async function tokenizeCard(input: CardFormInput): Promise<Omit<SavedCard, "cardBankName">> {
  return {
    cardToken: `tok_dummy_${Date.now()}`,
    cardAssociation: ASSOCIATIONS[getCardType(input.cardNumber)],
    lastFourDigits: input.cardNumber.slice(-4),
    // The form keeps MMYY; iyzico uses "12" and "2030".
    expireMonth: input.expiry.slice(0, 2),
    expireYear: `20${input.expiry.slice(2, 4)}`,
    cardHolderName: input.holderName
  }
}

import { BRAND_NAMES } from "@/features/checkout-card/constants/cards.constants"
import type { SavedCard } from "@/features/checkout-card/schemas/card.schema"

export function CardDetails({ card }: { card: SavedCard }) {
  // iyzico keeps "12" and "2030"; the card shows 12/30.
  const expiry = `${card.expireMonth}/${card.expireYear.slice(-2)}`

  return (
    <span className="flex min-w-0 flex-col gap-1 text-sm">
      <span className="font-medium">
        {card.cardBankName ? `${card.cardBankName} · ` : ""}
        {card.cardAssociation ? BRAND_NAMES[card.cardAssociation] : "Card"}
      </span>
      <span className="font-mono tabular-nums">•••• •••• •••• {card.lastFourDigits}</span>
      <span className="text-muted-foreground">
        {card.cardHolderName} · Expires {expiry}
      </span>
    </span>
  )
}

"use client"

import type { ReactNode } from "react"

import { zodResolver } from "@hookform/resolvers/zod"
import { maskResolver, useViraMask } from "@virastack/mask"
import { useForm } from "react-hook-form"

import { Button } from "@/components/ui/button"
import { Field, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { CARD_MASKS } from "@/features/checkout-card/constants/cards.constants"
import { useAddCard } from "@/features/checkout-card/hooks/use-add-card"
import { cardFormSchema } from "@/features/checkout-card/schemas/card.schema"
import type { CardFormInput, SavedCard } from "@/features/checkout-card/schemas/card.schema"

/** The mask reports a key such as `card.invalid`, for the form to word. Others are the schema's. */
function wordMaskError(message: string | undefined, maskMessage: string) {
  return message && /^[a-z]+\.[a-zA-Z]+$/.test(message) ? maskMessage : message
}

export function CardForm({ onSaved }: { onSaved: (saved: SavedCard) => void }) {
  const addCard = useAddCard()
  const form = useForm<CardFormInput>({
    resolver: maskResolver(CARD_MASKS, zodResolver(cardFormSchema)),
    defaultValues: { cardNumber: "", holderName: "", expiry: "", cvv: "" }
  })
  const { holderName, cardNumber, expiry, cvv } = useViraMask(form, CARD_MASKS)
  const { errors, isSubmitting } = form.formState

  const onSubmit = form.handleSubmit(async (input) => {
    try {
      onSaved(await addCard.mutateAsync(input))
    } catch {
      form.setError("root.server", { message: "Could not save the card. Try again." })
    }
  })

  return (
    <form onSubmit={onSubmit} noValidate className="flex flex-col gap-4">
      <FormField name="holderName" label={"Name on card"} error={errors.holderName?.message}>
        <Input
          {...holderName}
          id="holderName"
          autoComplete="cc-name"
          aria-invalid={Boolean(errors.holderName)}
          aria-describedby={errors.holderName ? "holderName-error" : undefined}
        />
      </FormField>
      <FormField
        name="cardNumber"
        label={"Card number"}
        error={wordMaskError(errors.cardNumber?.message, "Check the card number")}
      >
        <Input
          {...cardNumber}
          id="cardNumber"
          autoComplete="cc-number"
          placeholder="0000 0000 0000 0000"
          aria-invalid={Boolean(errors.cardNumber)}
          aria-describedby={errors.cardNumber ? "cardNumber-error" : undefined}
        />
      </FormField>
      <div className="grid gap-4 sm:grid-cols-2">
        <FormField
          name="expiry"
          label={"Expiry (MM/YY)"}
          error={wordMaskError(errors.expiry?.message, "Enter a valid future date")}
        >
          <Input
            {...expiry}
            id="expiry"
            autoComplete="cc-exp"
            placeholder="12/30"
            aria-invalid={Boolean(errors.expiry)}
            aria-describedby={errors.expiry ? "expiry-error" : undefined}
          />
        </FormField>
        <FormField
          name="cvv"
          label={"CVV"}
          error={wordMaskError(errors.cvv?.message, "Check the CVV")}
        >
          <Input
            {...cvv}
            id="cvv"
            autoComplete="cc-csc"
            placeholder="123"
            aria-invalid={Boolean(errors.cvv)}
            aria-describedby={errors.cvv ? "cvv-error" : undefined}
          />
        </FormField>
      </div>
      {errors.root?.server ? (
        <p role="alert" className="text-sm text-destructive">
          {errors.root.server.message}
        </p>
      ) : null}
      <Button type="submit" className="self-start" disabled={isSubmitting}>
        {isSubmitting ? "Saving…" : "Save card"}
      </Button>
    </form>
  )
}

type FormFieldProps = {
  name: string
  label: string
  error?: string
  children: ReactNode
}

function FormField({ name, label, error, children }: FormFieldProps) {
  return (
    <Field data-invalid={Boolean(error)}>
      <FieldLabel htmlFor={name}>{label}</FieldLabel>
      {children}
      {error ? <FieldError id={`${name}-error`}>{error}</FieldError> : null}
    </Field>
  )
}

"use client"

import { useState } from "react"

import { ArrowLeftIcon, PlusIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { CardDetails } from "@/features/checkout-card/components/CardDetails"
import { CardForm } from "@/features/checkout-card/components/CardForm"
import type { SavedCard } from "@/features/checkout-card/schemas/card.schema"

type CardPickerProps = {
  isOpen: boolean
  onOpenChange: (isOpen: boolean) => void
  cards: SavedCard[]
  selectedToken: string | null
  onSelect: (token: string) => void
}

export function CardPicker({ isOpen, onOpenChange, ...props }: CardPickerProps) {
  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[calc(100dvh-2rem)] max-w-[calc(100vw-2rem)] overflow-y-auto sm:max-w-lg">
        {/* Mounted only while open, so card details never outlive the dialog. */}
        <CardPickerContent {...props} onClose={() => onOpenChange(false)} />
      </DialogContent>
    </Dialog>
  )
}

type CardPickerContentProps = Omit<CardPickerProps, "isOpen" | "onOpenChange"> & {
  onClose: () => void
}

/** A saved card has no edit: its number is gone, so a changed card is a new card. */
function CardPickerContent({ cards, selectedToken, onSelect, onClose }: CardPickerContentProps) {
  const [draftToken, setDraftToken] = useState(selectedToken)
  const [isAdding, setIsAdding] = useState(cards.length === 0)

  if (isAdding) {
    return (
      <>
        <DialogHeader>
          <DialogTitle>Add new card</DialogTitle>
          <DialogDescription>
            The card number and CVV never leave this browser. The request carries a dummy token, the
            brand, the last four digits, the expiry and the name on the card.
          </DialogDescription>
        </DialogHeader>
        {cards.length > 0 ? (
          <Button
            variant="ghost"
            size="sm"
            className="justify-self-start"
            onClick={() => setIsAdding(false)}
          >
            <ArrowLeftIcon aria-hidden />
            Back to cards
          </Button>
        ) : null}
        <CardForm
          onSaved={(saved) => {
            onSelect(saved.cardToken)
            onClose()
          }}
        />
      </>
    )
  }

  return (
    <>
      <DialogHeader>
        <DialogTitle>Choose a card</DialogTitle>
      </DialogHeader>
      <RadioGroup
        aria-label={"Choose a card"}
        value={draftToken ?? ""}
        onValueChange={(value) => setDraftToken(String(value))}
      >
        {cards.map((card) => (
          <Label
            key={card.cardToken}
            className="flex cursor-pointer items-start gap-3 rounded-lg border p-4 font-normal has-data-checked:border-foreground/40 has-data-checked:bg-muted/40"
          >
            <RadioGroupItem value={card.cardToken} className="mt-0.5" />
            <CardDetails card={card} />
          </Label>
        ))}
      </RadioGroup>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <Button variant="outline" onClick={() => setIsAdding(true)}>
          <PlusIcon aria-hidden />
          Add new card
        </Button>
        <Button
          disabled={draftToken === null}
          onClick={() => {
            if (draftToken !== null) onSelect(draftToken)
            onClose()
          }}
        >
          Use this card
        </Button>
      </div>
    </>
  )
}

import { screen, within } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import type { UserEvent } from "@testing-library/user-event"
import { http, HttpResponse } from "msw/http"
import { beforeEach, describe, expect, it, vi } from "vitest"

import { siteConfig } from "@/config/site.config"

import { getCards } from "@/features/checkout-card/api/get-cards.api"
import { CheckoutCard } from "@/features/checkout-card/components/CheckoutCard"
import { CARDS_PATH } from "@/features/checkout-card/constants/cards.constants"
import { useCardSelectionStore } from "@/features/checkout-card/stores/card-selection.store"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

vi.mock("@/features/checkout-card/api/get-cards.api", { spy: true })

const ADD_URL = `${siteConfig.apiUrl}${CARDS_PATH}`

async function renderPayment() {
  renderWithProviders(<CheckoutCard />)
  return screen.findByRole("region", { name: "Payment method" })
}

async function openPicker(user: UserEvent) {
  await user.click(screen.getByRole("button", { name: "Change payment method" }))
  return screen.findByRole("dialog")
}

async function openForm(user: UserEvent) {
  const dialog = await openPicker(user)
  await user.click(within(dialog).getByRole("button", { name: "Add new card" }))
}

async function fillCard(user: UserEvent, number: string, expiry: string, cvv: string) {
  await user.type(await screen.findByLabelText("Card number"), number)
  await user.type(screen.getByLabelText("Name on card"), "Ömer Gülçiçek")
  await user.type(screen.getByLabelText("Expiry (MM/YY)"), expiry)
  await user.type(screen.getByLabelText("CVV"), cvv)
}

describe("CheckoutCard", () => {
  beforeEach(() => {
    useCardSelectionStore.setState({ selectedToken: null })
  })

  it("starts with the name, focuses it on an empty submit and keeps only letters", async () => {
    const user = userEvent.setup()
    await renderPayment()
    await openForm(user)

    const name = await screen.findByLabelText("Name on card")
    const inputs = within(screen.getByRole("dialog")).getAllByRole("textbox")
    expect(inputs[0]).toBe(name)

    await user.click(screen.getByRole("button", { name: "Save card" }))
    expect(name).toHaveFocus()
    expect(name).toHaveAccessibleDescription("Enter the name on the card")

    await user.type(name, "Ömer123  Gül")
    expect(name).toHaveValue("Ömer Gül")
  })

  it("opens straight on the form when there is no card yet", async () => {
    vi.mocked(getCards).mockResolvedValueOnce([])
    const user = userEvent.setup()
    await renderPayment()

    await user.click(screen.getByRole("button", { name: "Add card" }))

    const dialog = await screen.findByRole("dialog")
    expect(within(dialog).getByLabelText("Card number")).toBeInTheDocument()
    expect(within(dialog).queryByRole("button", { name: "Back to cards" })).toBeNull()
  })

  it("shows only the chosen card", async () => {
    const payment = await renderPayment()

    expect(within(payment).getByText(/Garanti BBVA/)).toBeInTheDocument()
    expect(within(payment).getByText(/0003/)).toBeInTheDocument()
    expect(screen.queryByText(/Akbank/)).not.toBeInTheDocument()
  })

  it("lists saved cards without an edit button and changes the card", async () => {
    const user = userEvent.setup()
    const payment = await renderPayment()

    const dialog = await openPicker(user)
    expect(within(dialog).getAllByRole("radio")).toHaveLength(3)
    expect(within(dialog).queryByRole("button", { name: /Edit/ })).not.toBeInTheDocument()

    await user.click(within(dialog).getByRole("radio", { name: /Akbank/ }))
    await user.click(within(dialog).getByRole("button", { name: "Use this card" }))

    expect(await within(payment).findByText(/Akbank/)).toBeInTheDocument()
    expect(useCardSelectionStore.getState().selectedToken).toBe("tok_dummy_akbank")
  })

  it("sends nothing while the fields are empty", async () => {
    let requests = 0
    server.use(
      http.post(ADD_URL, () => {
        requests += 1
        return HttpResponse.json({ status: 201, message: "Created" }, { status: 201 })
      })
    )
    const user = userEvent.setup()
    await renderPayment()

    await openForm(user)
    await user.click(await screen.findByRole("button", { name: "Save card" }))

    expect(await screen.findByText("Enter the card number")).toBeInTheDocument()
    expect(screen.getByText("Enter the name on the card")).toBeInTheDocument()
    expect(screen.getByText("Enter the expiry date")).toBeInTheDocument()
    expect(screen.getByText("Enter the CVV")).toBeInTheDocument()
    expect(requests).toBe(0)
  })

  it("rejects a number that fails the Luhn check and a past expiry", async () => {
    const user = userEvent.setup()
    await renderPayment()

    await openForm(user)
    await fillCard(user, "5400360000000004", "0120", "123")
    await user.click(screen.getByRole("button", { name: "Save card" }))

    expect(await screen.findByText("Check the card number")).toBeInTheDocument()
    expect(screen.getByText("Enter a valid future date")).toBeInTheDocument()
  })

  it("formats the fields and lets an Amex CVV have four digits", async () => {
    const user = userEvent.setup()
    await renderPayment()

    await openForm(user)
    await fillCard(user, "374427000000003", "1230", "1234")

    expect(screen.getByLabelText("Card number")).toHaveValue("3744 270000 00003")
    expect(screen.getByLabelText("Expiry (MM/YY)")).toHaveValue("12/30")
    expect(screen.getByLabelText("CVV")).toHaveValue("1234")
  })

  it("posts no card number or CVV, then shows the new card as chosen", async () => {
    let body = ""
    server.use(
      http.post(ADD_URL, async ({ request }) => {
        body = await request.text()
        return HttpResponse.json({ status: 201, message: "Created" }, { status: 201 })
      })
    )
    const user = userEvent.setup()
    const payment = await renderPayment()

    await openForm(user)
    await fillCard(user, "4543590000000006", "1230", "321")
    expect(screen.getByLabelText("Card number")).toHaveAttribute("autocomplete", "cc-number")
    await user.click(screen.getByRole("button", { name: "Save card" }))

    expect(await within(payment).findByText(/Visa/)).toBeInTheDocument()
    expect(within(payment).getByText(/0006/)).toBeInTheDocument()
    expect(body).toContain("tok_dummy_")
    expect(body).not.toContain("4543590000000006")
    expect(body).not.toContain("321")
    expect(screen.queryByRole("dialog")).not.toBeInTheDocument()
  })

  it("keeps the input and shows an error when saving fails", async () => {
    server.use(http.post(ADD_URL, () => HttpResponse.json({}, { status: 500 })))
    const user = userEvent.setup()
    await renderPayment()

    await openForm(user)
    await fillCard(user, "5400360000000003", "1230", "123")
    await user.click(screen.getByRole("button", { name: "Save card" }))

    expect(await screen.findByRole("alert")).toHaveTextContent(/Could not save/)
    expect(screen.getByLabelText("Name on card")).toHaveValue("Ömer Gülçiçek")
  })
})

"use client"

import { useState } from "react"

import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { CardDetails } from "@/features/checkout-card/components/CardDetails"
import { CardPicker } from "@/features/checkout-card/components/CardPicker"
import { useCards } from "@/features/checkout-card/hooks/use-cards"
import { useCheckoutCard } from "@/features/checkout-card/hooks/use-checkout-card"
import { useCardSelectionStore } from "@/features/checkout-card/stores/card-selection.store"

/** Only the chosen card shows on the page; the rest wait in the picker. */
export function CheckoutCard() {
  const cards = useCards()
  const { card } = useCheckoutCard()
  const setSelectedToken = useCardSelectionStore((state) => state.setSelectedToken)
  const [isPickerOpen, setIsPickerOpen] = useState(false)

  if (cards.isPending) {
    return (
      <div role="status" aria-label={"Loading cards"}>
        <Skeleton className="h-24 w-full" />
      </div>
    )
  }

  if (cards.isError) {
    return (
      <div role="alert" className="flex flex-col items-start gap-3 rounded-lg border p-4">
        <p className="text-sm">Could not load your cards</p>
        <Button variant="outline" onClick={() => cards.refetch()}>
          Retry
        </Button>
      </div>
    )
  }

  return (
    <section aria-label={"Payment method"} className="flex min-w-0 flex-col gap-3">
      <h3 className="text-lg font-semibold tracking-tight">Payment method</h3>
      <div className="flex items-start justify-between gap-3 rounded-lg border p-4">
        {card ? (
          <CardDetails card={card} />
        ) : (
          <p className="text-sm text-muted-foreground">No saved card yet.</p>
        )}
        <Button
          variant="outline"
          size="sm"
          className="shrink-0"
          aria-label={card ? "Change payment method" : undefined}
          onClick={() => setIsPickerOpen(true)}
        >
          {card ? "Change" : "Add card"}
        </Button>
      </div>
      <CardPicker
        isOpen={isPickerOpen}
        onOpenChange={setIsPickerOpen}
        cards={cards.data}
        selectedToken={card?.cardToken ?? null}
        onSelect={setSelectedToken}
      />
    </section>
  )
}

import type { CardAssociation, SavedCard } from "@/features/checkout-card/schemas/card.schema"

/** DummyJSON has no card API; this address only answers 201 Created. Point it at your own API. */
export const CARDS_PATH = "/http/201"

/**
 * Starting data until you connect an API. Like a real saved card, each keeps only its last four
 * digits. They come from iyzico's sandbox test cards, which do no real payment:
 * https://docs.iyzico.com/en/add-ons/test-cards
 */
export const DUMMY_CARDS: SavedCard[] = [
  {
    cardToken: "tok_dummy_garanti",
    cardAssociation: "MASTER_CARD",
    lastFourDigits: "0003",
    expireMonth: "12",
    expireYear: "2030",
    cardHolderName: "Ömer Gülçiçek",
    cardBankName: "Garanti BBVA"
  },
  {
    cardToken: "tok_dummy_akbank",
    cardAssociation: "MASTER_CARD",
    lastFourDigits: "0006",
    expireMonth: "12",
    expireYear: "2030",
    cardHolderName: "Ömer Gülçiçek",
    cardBankName: "Akbank"
  },
  {
    cardToken: "tok_dummy_is_bankasi",
    cardAssociation: "VISA",
    lastFourDigits: "0006",
    expireMonth: "12",
    expireYear: "2030",
    cardHolderName: "Ömer Gülçiçek",
    cardBankName: "Türkiye İş Bankası"
  }
]

/** The masks, shared by the form and its resolver. The CVV follows the card's network. */
export const CARD_MASKS = {
  holderName: { preset: "fullName", autoComplete: "cc-name" },
  cardNumber: "card",
  expiry: "expiry",
  cvv: { preset: "cvv", from: "cardNumber" }
} as const

export const BRAND_NAMES: Record<CardAssociation, string> = {
  VISA: "Visa",
  MASTER_CARD: "Mastercard",
  AMERICAN_EXPRESS: "American Express",
  TROY: "Troy"
}

"use client"

import { useMutation, useQueryClient } from "@tanstack/react-query"

import { cardKeys } from "@/features/checkout-card/api/query-keys"
import { saveCard } from "@/features/checkout-card/api/save-card.api"
import { tokenizeCard } from "@/features/checkout-card/api/tokenize-card"
import type { CardFormInput, SavedCard } from "@/features/checkout-card/schemas/card.schema"

export function useAddCard() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (input: CardFormInput) => saveCard(await tokenizeCard(input)),
    // With a real API, invalidate `cardKeys.all` instead.
    onSuccess: (saved) =>
      queryClient.setQueryData<SavedCard[]>(cardKeys.all, (cards = []) => [...cards, saved])
  })
}

"use client"

import { useQuery } from "@tanstack/react-query"

import { cardsQueryOptions } from "@/features/checkout-card/api/card.queries"

export function useCards() {
  return useQuery(cardsQueryOptions)
}

"use client"

import { useCards } from "@/features/checkout-card/hooks/use-cards"
import { useCardSelectionStore } from "@/features/checkout-card/stores/card-selection.store"

/** What the module gives the next checkout step: the chosen card, with no card number or CVV. */
export function useCheckoutCard() {
  const { data: cards = [] } = useCards()
  const selectedToken = useCardSelectionStore((state) => state.selectedToken)

  return { card: cards.find(({ cardToken }) => cardToken === selectedToken) ?? cards[0] ?? null }
}

import { z } from "zod"

export const cardFormSchema = z.object({
  cardNumber: z.string().min(1, "Enter the card number"),
  holderName: z.string().trim().min(1, "Enter the name on the card").max(60, "This is too long"),
  expiry: z.string().min(1, "Enter the expiry date"),
  cvv: z.string().min(1, "Enter the CVV")
})

export const savedCardResponseSchema = z.object({ status: z.number() })

export type CardFormInput = z.infer<typeof cardFormSchema>

/** iyzico's card networks. */
export type CardAssociation = "VISA" | "MASTER_CARD" | "AMERICAN_EXPRESS" | "TROY"

/**
 * What may be kept and shown, named after iyzico's card storage so its answer maps over:
 * https://docs.iyzico.com/en/advanced/card-storage
 * There is no field for a card number or CVV on purpose.
 */
export type SavedCard = {
  cardToken: string
  /** `null` when the number belongs to none of iyzico's networks. */
  cardAssociation: CardAssociation | null
  lastFourDigits: string
  expireMonth: string
  expireYear: string
  cardHolderName: string
  /** iyzico returns it for cards issued in Türkiye. */
  cardBankName: string | null
}

import { create } from "zustand"

type CardSelectionState = {
  /** Only the token: the cards themselves stay in the Query cache. */
  selectedToken: string | null
  setSelectedToken: (token: string) => void
}

// Client-only UI state, so a module-level store is fine. Not persisted, and never holds card data.
export const useCardSelectionStore = create<CardSelectionState>()((set) => ({
  selectedToken: null,
  setSelectedToken: (selectedToken) => set({ selectedToken })
}))
